// Color cycling: cozy pixel-art scenes animated the 8-bit way. Each is drawn
// once, a byte a cell, and from then on only its palette moves: ranges of
// colors rotate where the art laid them out in the direction of travel, so
// water falls, waves roll in, rain and snow come down, smoke rises, flames
// lick and stars twinkle. A frame costs the app a palette of 256 colors, and
// the panel rewrites only the cells whose color changed (frameos.pixels, the
// 8-bit palette mode). Swipe left or right for the next or previous scene.
import { setSeed } from './random'
import { Art, cycled } from './art'
import { makeFalls } from './falls'
import { makeHarbor } from './harbor'
import { makeRain } from './rain'
import { makeSnow } from './snow'
import { makeAurora } from './aurora'
import { makeCampfire } from './campfire'

const SCENES: Record<string, (cols: number, rows: number) => Art> = {
  falls: makeFalls,
  harbor: makeHarbor,
  rain: makeRain,
  snow: makeSnow,
  aurora: makeAurora,
  campfire: makeCampfire,
}
const ORDER = Object.keys(SCENES)

// What outlives a render while the interpreter does. An ESP32 short of
// memory drops the interpreter, and the scene is drawn again.
let key = ''
let art: Art | null = null
let size = 1
let renders = 0
const palette = new Uint32Array(256)

function sceneOf(config: any): string {
  return SCENES[config.scene] ? config.scene : ORDER[0]
}

export function get(app, context) {
  const config = app.config
  const scene = sceneOf(config)
  const width = context.imageWidth || app.frame.width
  const height = context.imageHeight || app.frame.height
  // Automatic: about 240 cells across the short side, 160 on an ESP32, where
  // drawing the scene the first time is the slow part.
  const asked = Math.round(Number(config.pixelSize) || 0)
  const px = asked >= 1 ? Math.min(32, asked) : Math.max(2, Math.round(Math.min(width, height) / (app.frame.embedded ? 160 : 240)))
  const seed = Math.round(Number(config.seed) || 0)
  const next = [scene, px, width, height, seed].join(':')
  if (next !== key || !art) {
    key = next
    setSeed(seed > 0 ? seed : Date.now() ^ (Math.random() * 0x7fffffff))
    art = SCENES[scene](Math.max(8, Math.floor(width / px)), Math.max(8, Math.floor(height / px)))
    size = px
    renders = 0
  }
  // The colors move with the clock, so they keep their pace at any frame rate
  // and are where the time says after a deep sleep; a fixed step a render
  // instead makes every render the same, from the first.
  const step = Number(config.msPerRender) || 0
  cycled(art, step > 0 ? renders++ * step : Date.now(), palette)
  return frameos.pixels(art.cells, palette, { width: art.cols, height: art.rows, pixelSize: size })
}

export function onEvent(app, context) {
  if (context.event !== 'swipe') return false
  const direction = (context.payload || {}).direction
  const step = direction === 'left' ? 1 : direction === 'right' ? -1 : 0
  if (!step) return false
  const at = ORDER.indexOf(sceneOf(app.config))
  frameos.setState('scene', ORDER[(at + step + ORDER.length) % ORDER.length])
  return true
}

sources.art.ts:
// A scene's picture in the 8-bit palette mode: a byte a cell, each an index
// into 256 colors, some of which cycle. The picture is drawn once; what moves
// afterwards is only the colors, so a frame costs a palette and the panel
// rewrites only the cells whose color changed.
import { random } from './random'

/** Colors that rotate through their range, `speed` places a second
 *  (negative: the other way); `blend` mixes neighbors for the moments between. */
export type Cycle = { from: number; count: number; speed: number; blend: boolean }

// The 4x4 ordered-dither matrix, as thresholds in (0, 1).
const BAYER = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5].map((v) => (v + 0.5) / 16)

export function mix(a: number, b: number, f: number): number {
  const ch = (s: number) => {
    const x = (a >> s) & 255
    return Math.round(x + (((b >> s) & 255) - x) * f) << s
  }
  return ch(16) | ch(8) | ch(0)
}

/** Stops [at (0..1), 0xRRGGBB] read at `at`. */
export function at(stops: number[][], t: number): number {
  let k = 0
  while (k < stops.length - 2 && t > stops[k + 1][0]) k++
  const [a0, c0] = stops[k]
  const [a1, c1] = stops[k + 1]
  return mix(c0, c1, Math.max(0, Math.min(1, a1 === a0 ? 0 : (t - a0) / (a1 - a0))))
}

/** `v` (0..1) as one of `n` levels, dithered by place so a gradient of a few
 *  colors reads as a smooth one. */
export function level(v: number, n: number, x: number, y: number): number {
  const l = Math.floor(v * (n - 1) + BAYER[((y & 3) << 2) | (x & 3)])
  return l < 0 ? 0 : l >= n ? n - 1 : l
}

/** Smooth noise in about 0..1, `scale` cells to a feature, seeded. */
export function noise(scale: number) {
  const g = new Float32Array(64 * 64)
  for (let i = 0; i < g.length; i++) g[i] = random()
  return (x: number, y: number) => {
    x /= scale
    y /= scale
    const xi = Math.floor(x)
    const yi = Math.floor(y)
    let fx = x - xi
    let fy = y - yi
    fx = fx * fx * (3 - 2 * fx)
    fy = fy * fy * (3 - 2 * fy)
    const r0 = (yi & 63) << 6
    const r1 = ((yi + 1) & 63) << 6
    const a = g[r0 | (xi & 63)]
    const b = g[r0 | ((xi + 1) & 63)]
    const c = g[r1 | (xi & 63)]
    const d = g[r1 | ((xi + 1) & 63)]
    return a + (b - a) * fx + (c - a) * fy + (a - b - c + d) * fx * fy
  }
}

export class Art {
  cols: number
  rows: number
  cells: Uint8Array
  colors = new Uint32Array(256)
  used = 0
  cycles: Cycle[] = []

  constructor(cols: number, rows: number) {
    this.cols = cols
    this.rows = rows
    this.cells = new Uint8Array(cols * rows)
  }

  /** One more color; its index (the last one when all 256 are taken). */
  add(rgb: number): number {
    if (this.used >= 256) return 255
    this.colors[this.used] = rgb
    return this.used++
  }

  /** `count` colors through `stops`, still; the first one's index. */
  ramp(count: number, stops: number[][]): number {
    const from = this.used
    for (let i = 0; i < count; i++) this.add(at(stops, count === 1 ? 0 : i / (count - 1)))
    return from
  }

  /** Colors that cycle; the first one's index. */
  cycle(colors: number[], speed: number, blend = true): number {
    const from = this.used
    for (const c of colors) this.add(c)
    this.cycles.push({ from, count: this.used - from, speed, blend })
    return from
  }

  /** Something passing over what is drawn (rain, snow, a star's twinkle):
   *  one cycling range of `count` per color it passes over, entry i of it
   *  `shade(under, i)`. The returned function puts cell `at` on the range for
   *  the color it shows now, at `phase`; a cell whose color has no room left
   *  for a range keeps its color. */
  over(count: number, speed: number, blend: boolean, shade: (under: number, i: number) => number) {
    const ranges = new Map<number, number>()
    return (at: number, phase: number) => {
      const under = this.cells[at]
      let from = ranges.get(under)
      if (from === undefined) {
        if (this.used + count > 256) return
        const bg = this.colors[under]
        const colors: number[] = []
        for (let i = 0; i < count; i++) colors.push(shade(bg, i))
        from = this.cycle(colors, speed, blend)
        ranges.set(under, from)
      }
      this.cells[at] = from + (((phase % count) + count) % count)
    }
  }

  /** A filled ellipse of `index` (or `pick(x, y)`), centered at (cx, cy). */
  ellipse(cx: number, cy: number, rx: number, ry: number, index: number | ((x: number, y: number) => number)) {
    const pick = typeof index === 'number' ? null : index
    for (let y = Math.max(0, Math.floor(cy - ry)); y <= Math.min(this.rows - 1, Math.ceil(cy + ry)); y++) {
      for (let x = Math.max(0, Math.floor(cx - rx)); x <= Math.min(this.cols - 1, Math.ceil(cx + rx)); x++) {
        const dx = (x - cx) / rx
        const dy = (y - cy) / ry
        if (dx * dx + dy * dy <= 1) this.cells[y * this.cols + x] = pick ? pick(x, y) : (index as number)
      }
    }
  }

  /** A filled rectangle. */
  rect(x0: number, y0: number, w: number, h: number, index: number) {
    for (let y = Math.max(0, y0); y < Math.min(this.rows, y0 + h); y++) {
      const row = y * this.cols
      this.cells.fill(index, row + Math.max(0, x0), row + Math.min(this.cols, x0 + w))
    }
  }
}

/** The palette at `ms` of cycling: `base` with each range rotated. */
export function cycled(art: Art, ms: number, out: Uint32Array) {
  const base = art.colors
  out.set(base)
  for (const c of art.cycles) {
    const n = c.count
    let shift = ((ms / 1000) * c.speed) % n
    if (shift < 0) shift += n
    const whole = Math.floor(shift)
    const f = c.blend ? shift - whole : 0
    for (let i = 0; i < n; i++) {
      const a = base[c.from + ((i - whole + n) % n)]
      out[c.from + i] = f > 0 ? mix(a, base[c.from + ((i - whole - 1 + 2 * n) % n)], f) : a
    }
  }
}

