// One xorshift32 for every effect, so a seed is the same picture on every
// frame type. It stays a small integer in QuickJS (no float, no call to
// Math.random in a loop).
let s = 1

export function setSeed(seed: number) {
  s = seed | 0 || 1
}

/** A 32-bit integer. */
export function nextInt(): number {
  s ^= s << 13
  s ^= s >>> 17
  s ^= s << 5
  return s
}

/** A number in [0, 1). */
export function random(): number {
  return (nextInt() >>> 0) / 4294967296
}

/** A number in [lo, hi). */
export function between(lo: number, hi: number): number {
  return lo + random() * (hi - lo)
}

sources.falls.ts:
// Falls: a waterfall at dusk between two cliffs, pouring into a pool. The
// water's streaks, the foam where it lands and the rings across the pool are
// ranges of colors laid down the way they move, and the stars twinkle.
import { Art, level, mix, noise } from './art'
import { random } from './random'

export function makeFalls(cols: number, rows: number) {
  const art = new Art(cols, rows)
  const cells = art.cells
  const sky = art.ramp(12, [[0, 0x1b1446], [0.4, 0x4a2468], [0.75, 0xb4527c], [1, 0xf2a06e]])
  const far = art.ramp(3, [[0, 0x3d2a5e], [1, 0x6b3f72]])
  const rock = art.ramp(6, [[0, 0x1c1526], [0.5, 0x3e2b44], [1, 0x7a4f5c]])
  const pine = art.ramp(2, [[0, 0x0d1416], [1, 0x1a2622]])
  const bank = art.ramp(3, [[0, 0x111a17], [1, 0x2c3b2c]])
  const fall = art.cycle([0xffffff, 0xf0faff, 0xdcf1fc, 0xc4e4f7, 0xaad3ef, 0x8fc0e5, 0x77acd9, 0x6a9fd0,
    0x77acd9, 0x8fc0e5, 0xaad3ef, 0xc4e4f7, 0xdcf1fc, 0xeaf7fe, 0xf8fdff, 0xffffff], 20)
  const edge = art.cycle([0x9cc6e6, 0x7aa8d2, 0x5c8bba, 0x4a73a0, 0x3f6694, 0x36598a, 0x3f6694, 0x4a73a0,
    0x5c8bba, 0x6d9cc8, 0x86b6dc, 0xa8cfec], 20)
  const foam = art.cycle([0xffffff, 0xe4f3fc, 0xbcd8ee, 0x8fb8dc, 0x6f9ccb, 0x8fb8dc, 0xc6e0f2, 0xf2faff,
    0xd2e8f6, 0x9cc2e2, 0x7aa6d2, 0xa8cbe8], 6)
  const pool = art.cycle([0x1b3458, 0x203c63, 0x27486f, 0x30567c, 0x3d6688, 0x30567c, 0x27486f, 0x203c63,
    0x1b3458, 0x182f50, 0x162b4a, 0x182f50], 3)

  const horizon = Math.floor(rows * 0.5)
  const n1 = noise(cols / 5)
  const n2 = noise(cols / 9)
  const tex = noise(3)

  // The sky, darkest at the top.
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) cells[y * cols + x] = sky + level(Math.min(1, y / horizon), 12, x, y)
  }
  // A far range, hazier toward its foot.
  for (let x = 0; x < cols; x++) {
    const top = Math.floor(rows * (0.3 + 0.1 * n1(x, 0)))
    for (let y = top; y < horizon; y++) cells[y * cols + x] = far + level((y - top) / (horizon - top), 3, x, y)
  }

  // The cliffs: a plateau with a notch the water pours through.
  const cx = cols / 2
  const lip = Math.floor(rows * 0.44)
  const poolTop = Math.floor(rows * 0.74)
  const half = (y: number) => cols * (0.06 + 0.025 * Math.max(0, (y - lip) / (poolTop - lip)))
  const cliffTop = new Int32Array(cols)
  for (let x = 0; x < cols; x++) {
    const away = Math.abs(x - cx) / cols
    cliffTop[x] = Math.floor(rows * (0.42 + 0.05 * n2(x, 3) - 0.1 * Math.min(1, away * 2.2)) + (away < 0.09 ? rows * 0.02 : 0))
    for (let y = cliffTop[x]; y < poolTop; y++) {
      // Lit from the sunset above: lighter near the top edge, strata across.
      const near = Math.max(0, 1 - Math.abs(x - cx) / (cols * 0.16))
      const light = 0.9 - 0.7 * ((y - cliffTop[x]) / (poolTop - cliffTop[x])) - 0.35 * near +
        0.45 * (tex(x * 0.8, y * 2.5) - 0.5)
      cells[y * cols + x] = rock + level(Math.max(0, Math.min(1, light)), 6, x, y)
    }
  }
  // Pines along the edge.
  for (let x = 2; x < cols - 2; x += 2 + Math.floor(random() * 4)) {
    if (Math.abs(x - cx) < cols * 0.1) continue
    const h = Math.floor(rows * (0.03 + 0.05 * random()))
    const base = cliffTop[x] + 1
    for (let k = 0; k < h; k++) {
      const w = Math.floor((k / h) * h * 0.35)
      for (let dx = -w; dx <= w; dx++) {
        const xx = x + dx
        if (xx >= 0 && xx < cols && base - h + k >= 0) cells[(base - h + k) * cols + xx] = pine + (dx < 0 ? 1 : 0)
      }
    }
  }

  // The water: streaks down the fall, each column at its own offset, so the
  // range rotating reads as water falling. Darker at its sides.
  const offsets = new Int32Array(cols + 1)
  for (let x = 0; x < cols; x += 2) offsets[x] = offsets[x + 1] = Math.floor(random() * 16)
  for (let y = lip; y < poolTop + 2; y++) {
    const w = half(y)
    for (let x = Math.floor(cx - w); x <= Math.ceil(cx + w); x++) {
      const side = Math.abs(x - cx) / w
      const at = y * cols + x
      if (side > 1) continue
      cells[at] = side > 0.82 ? edge + (((y + offsets[x]) % 12) + 12) % 12 : fall + (((y + offsets[x]) % 16) + 16) % 16
    }
  }

  // The pool, rings spreading from where the water lands.
  for (let y = poolTop; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      const dx = (x - cx) / cols
      const dy = ((y - poolTop) / rows) * 3.2
      const d = Math.sqrt(dx * dx + dy * dy) * cols * 0.5
      cells[y * cols + x] = pool + (Math.floor(d + 2.5 * tex(x, y * 2)) % 12)
    }
  }
  // Banks of rock and grass in the corners.
  for (let x = 0; x < cols; x++) {
    const away = Math.abs(x - cx) / cols
    const top = Math.floor(rows * (1.12 - away * 0.7) + 4 * n1(x * 3, 9))
    for (let y = Math.max(poolTop, top); y < rows; y++) {
      cells[y * cols + x] = bank + level(0.95 - (y - top) / (rows * 0.3) + 0.4 * (tex(x * 3, y * 3) - 0.5), 3, x, y)
    }
  }
  // Foam where it lands, churning outward.
  const foamW = cols * 0.17
  const foamH = rows * 0.05
  for (let y = poolTop - 2; y < poolTop + foamH; y++) {
    for (let x = Math.floor(cx - foamW); x <= Math.ceil(cx + foamW); x++) {
      const dx = (x - cx) / foamW
      const dy = (y - poolTop) / foamH
      const d = Math.sqrt(dx * dx + dy * dy * (dy < 0 ? 6 : 1))
      if (d > 0.75 + 0.35 * tex(x * 3, y * 3)) continue
      cells[y * cols + x] = foam + (Math.floor(d * 10 + 4 * tex(x * 2.5, y * 2.5)) % 12)
    }
  }

  // Stars over the darkest of the sky, each at its own point of a slow twinkle.
  const twinkle = art.over(10, 2.5, true, (under, i) =>
    i === 4 ? mix(under, 0xffffff, 0.95) : i === 3 || i === 5 ? mix(under, 0xffffff, 0.45) : under)
  for (let i = Math.floor((cols * rows) / 300); i > 0; i--) {
    const x = Math.floor(random() * cols)
    const y = Math.floor(random() * rows * 0.3)
    if (y < cliffTop[x] - 2) twinkle(y * cols + x, Math.floor(random() * 10))
  }

  return art
}

