// Harbor: the sun going down over the sea. Waves roll in as bands of color
// laid from the horizon to the shore, the sun's path glitters, and the
// lighthouse on the point breathes its light.
import { Art, level, mix, noise } from './art'
import { random } from './random'

export function makeHarbor(cols: number, rows: number) {
  const art = new Art(cols, rows)
  const cells = art.cells
  const sky = art.ramp(14, [[0, 0x19244f], [0.35, 0x473a78], [0.7, 0xd0646a], [0.9, 0xf59a62], [1, 0xffc879]])
  const cloud = art.ramp(4, [[0, 0x6a3f6e], [0.5, 0xc25f6c], [1, 0xffa877]])
  const sun = art.ramp(3, [[0, 0xffd27a], [1, 0xfff6d8]])
  const land = art.ramp(3, [[0, 0x0f1020], [1, 0x2a2238]])
  const tower = art.ramp(3, [[0, 0x8a7f96], [0.5, 0xd8cfd8], [1, 0xfff3ea]])
  const band = art.add(0x9a2f45)
  const dark = art.add(0x14131f)
  const farSea = art.cycle([0x6b4a7e, 0x7a5584, 0x8b6088, 0x9a6a8a, 0x8b6088, 0x7a5584, 0x6b4a7e, 0x5f4277,
    0x553c70, 0x4d376a, 0x553c70, 0x5f4277], 3)
  const nearSea = art.cycle([0x2b3e6e, 0x324a7a, 0x3b5687, 0x476592, 0x5a789f, 0x476592, 0x3b5687, 0x324a7a,
    0x2b3e6e, 0x26376a, 0x223163, 0x26376a], 3)
  const glitter = art.cycle([0xfff0b0, 0xffc56e, 0xd8805e, 0x8e5a72, 0x5d4878, 0x8e5a72, 0xd8805e, 0xffc56e,
    0xffe08e, 0xe89a62, 0xa56470, 0x6b4f7a], 7, false)
  const lamp = art.cycle([0x3a2a2a, 0x5a3a2a, 0x8a5a2a, 0xc8862e, 0xffc24a, 0xffeaa0, 0xffffff, 0xffeaa0,
    0xffc24a, 0xc8862e, 0x8a5a2a, 0x5a3a2a, 0x3a2a2a, 0x3a2a2a, 0x3a2a2a, 0x3a2a2a], 5)

  const horizon = Math.floor(rows * 0.56)
  const n = noise(cols / 6)
  const tex = noise(4)
  const sunX = cols * 0.64
  const sunY = horizon - rows * 0.02
  const sunR = Math.min(cols, rows) * 0.08

  for (let y = 0; y < horizon; y++) {
    for (let x = 0; x < cols; x++) {
      const glow = Math.max(0, 1 - Math.hypot((x - sunX) / cols, (y - sunY) / rows) * 2.2) * 0.25
      cells[y * cols + x] = sky + level(Math.min(1, y / horizon + glow), 14, x, y)
    }
  }
  // Long thin clouds, lit from below.
  for (let y = Math.floor(rows * 0.12); y < horizon - rows * 0.08; y++) {
    for (let x = 0; x < cols; x++) {
      const v = n(x * 0.5, y * 4) * 0.7 + tex(x, y * 3) * 0.3
      if (v > 0.62) cells[y * cols + x] = cloud + level((v - 0.62) * 3 + (y / horizon) * 0.6, 4, x, y)
    }
  }
  // The sun, half under.
  art.ellipse(sunX, sunY, sunR, sunR, (x, y) => (y < horizon ? sun + level(1 - Math.hypot(x - sunX, y - sunY) / sunR, 3, x, y) : cells[y * cols + x]))

  // The sea: the farther a row, the thinner its waves; the bands' index grows
  // toward the shore, so the cycle rolls them in.
  for (let y = horizon; y < rows; y++) {
    const z = (y - horizon + 1) / (rows - horizon)
    for (let x = 0; x < cols; x++) {
      const b = Math.floor(Math.sqrt(z) * 34 + 2.5 * tex(x * 0.4, y * 1.5))
      cells[y * cols + x] = (z < 0.3 ? farSea : nearSea) + (b % 12)
    }
  }
  // The sun's path on the water.
  for (let y = horizon; y < rows; y++) {
    const z = (y - horizon + 1) / (rows - horizon)
    const w = cols * (0.02 + 0.12 * z)
    for (let x = Math.floor(sunX - w); x <= sunX + w; x++) {
      if (x < 0 || x >= cols) continue
      const near = 1 - Math.abs(x - sunX) / w
      if (random() < near * near * (0.8 - 0.4 * z)) cells[y * cols + x] = glitter + Math.floor(random() * 12)
    }
  }

  // The point, its lighthouse and a boat.
  const pointX = cols * 0.34
  for (let x = 0; x < pointX; x++) {
    const top = Math.floor(horizon - rows * 0.04 + rows * 0.08 * (x / pointX) ** 2 - rows * 0.05 * n(x * 2, 5))
    for (let y = top; y < rows; y++) {
      if (y > horizon + rows * 0.03 * (1 - x / pointX)) break
      cells[y * cols + x] = land + level(0.6 - (y - top) / (rows * 0.3) + 0.4 * (tex(x * 2, y * 2) - 0.5), 3, x, y)
    }
  }
  const tx = Math.floor(cols * 0.14)
  const tw = Math.max(3, Math.floor(cols * 0.045))
  const tTop = Math.floor(horizon - rows * 0.24)
  const tBase = Math.floor(horizon - rows * 0.03)
  for (let y = tTop; y < tBase; y++) {
    const w = tw * (0.75 + 0.25 * (y - tTop) / (tBase - tTop))
    const stripe = Math.floor(((y - tTop) / (tBase - tTop)) * 5) % 2 === 1
    for (let x = Math.floor(tx - w / 2); x < tx + w / 2; x++) {
      const side = (x - (tx - w / 2)) / w
      cells[y * cols + x] = stripe ? band : tower + level(1 - side, 3, x, y)
    }
  }
  art.rect(tx - Math.floor(tw / 2) - 1, tTop - 1, tw + 2, 1, dark)
  art.rect(tx - Math.floor(tw / 2), tTop - Math.floor(tw * 0.8) - 1, tw, Math.floor(tw * 0.8), lamp)
  art.rect(tx - Math.floor(tw / 2) - 1, tTop - Math.floor(tw * 0.8) - 2, tw + 2, 1, dark)
  // The boat: a hull and two sails against the glitter.
  const bx = Math.floor(cols * 0.8)
  const by = Math.floor(horizon + rows * 0.06)
  const bs = Math.max(4, Math.floor(cols * 0.06))
  for (let k = 0; k < bs; k++) {
    for (let x = bx - Math.floor(k * 0.55); x <= bx; x++) cells[(by - bs + k) * cols + x] = dark
    for (let x = bx + 1; x <= bx + 1 + Math.floor(k * 0.35); x++) cells[(by - bs + k) * cols + x] = dark
  }
  art.rect(bx - Math.floor(bs * 0.7), by, Math.floor(bs * 1.4), Math.max(1, Math.floor(bs / 4)), dark)
  // A few stars before dark.
  const twinkle = art.over(10, 2, true, (under, i) => (i === 4 ? mix(under, 0xffffff, 0.8) : i === 3 || i === 5 ? mix(under, 0xffffff, 0.35) : under))
  for (let i = Math.floor((cols * rows) / 900); i > 0; i--) {
    const x = Math.floor(random() * cols)
    const y = Math.floor(random() * rows * 0.15)
    twinkle(y * cols + x, Math.floor(random() * 10))
  }
  return art
}

