// Rain: a village on a hill on a wet night. The rain falls along slanted
// tracks, one range of colors for each color it falls past, puddles ring
// where the drops land, and a window or two flickers.
import { Art, level, mix, noise } from './art'
import { random } from './random'

export function makeRain(cols: number, rows: number) {
  const art = new Art(cols, rows)
  const cells = art.cells
  const sky = art.ramp(6, [[0, 0x0b1020], [1, 0x27304a]])
  const cloud = art.ramp(3, [[0, 0x1e2538], [1, 0x3b4560]])
  const hill = art.ramp(3, [[0, 0x0c1418], [1, 0x1d2a2c]])
  const wall = art.ramp(3, [[0, 0x1a1a24], [1, 0x34303c]])
  const roof = art.ramp(2, [[0, 0x150f16], [1, 0x2c1f26]])
  const road = art.ramp(4, [[0, 0x14161e], [1, 0x3a3640]])
  const glow = art.ramp(5, [[0, 0x2a2a34], [0.6, 0x6a5440], [1, 0xd8a85a]])
  const window = art.add(0xffcf6a)
  const lampHead = art.add(0xfff2c0)
  const post = art.add(0x0a0a0e)
  const flicker = art.cycle([0xffcf6a, 0xffc860, 0xf2b858, 0xffd476, 0xe8a850, 0xffcf6a, 0xffe090, 0xf6bc5c], 3, false)
  const puddle = art.cycle([0x3a3e4c, 0x4c5262, 0x6a6e7c, 0x4c5262, 0x3a3e4c, 0x30343f, 0x2c303a, 0x30343f], 5)

  const ground = Math.floor(rows * 0.72)
  const n = noise(cols / 4)
  const tex = noise(3)
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) cells[y * cols + x] = sky + level(y / ground, 6, x, y)
  }
  for (let y = 0; y < rows * 0.4; y++) {
    for (let x = 0; x < cols; x++) {
      const v = n(x * 0.6, y * 1.5)
      if (v > 0.55) cells[y * cols + x] = cloud + level((v - 0.55) * 3, 3, x, y)
    }
  }
  // The hill the village sits on.
  const hillTop = new Int32Array(cols)
  for (let x = 0; x < cols; x++) {
    hillTop[x] = Math.floor(rows * (0.5 + 0.08 * Math.cos((x / cols - 0.4) * 3)) + rows * 0.04 * n(x, 7))
    for (let y = hillTop[x]; y < ground; y++) cells[y * cols + x] = hill + level((y - hillTop[x]) / (rows * 0.3), 3, x, y)
  }
  // Houses along the hill, windows lit.
  const flickering = new Set([1, 4])
  let k = 0
  for (let x = Math.floor(cols * 0.04); x < cols * 0.92; k++) {
    const w = Math.floor(cols * (0.08 + 0.05 * random()))
    const h = Math.floor(rows * (0.07 + 0.05 * random()))
    const base = Math.min(hillTop[x], hillTop[Math.min(cols - 1, x + w)]) + Math.floor(rows * 0.04)
    art.rect(x, base - h, w, h, wall + Math.floor(random() * 3))
    const peak = Math.floor(w * 0.45)
    for (let r = 0; r < peak; r++) {
      const rw = Math.max(1, Math.round(((w + 2) * (r + 1)) / peak))
      art.rect(x + ((w - rw) >> 1), base - h - peak + r, rw, 1, roof + (r % 3 === 0 ? 1 : 0))
    }
    for (let wx = x + 2; wx < x + w - 2; wx += 4) {
      if (random() < 0.3) continue
      art.rect(wx, base - h + 2, 2, 2, flickering.has(k) ? flicker + Math.floor(random() * 8) : window)
    }
    x += w + 2 + Math.floor(random() * cols * 0.06)
  }
  // The road, a lamp and its pool of light.
  const lampX = Math.floor(cols * 0.7)
  const lampY = Math.floor(ground - rows * 0.2)
  for (let y = ground; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      const lit = Math.max(0, 1 - Math.hypot((x - lampX) / cols, ((y - ground) / rows) * 2.5) * 3)
      cells[y * cols + x] = road + level(0.3 + 0.3 * (tex(x * 1.5, y * 4) - 0.5) + lit * 0.7, 4, x, y)
    }
  }
  for (let y = lampY - rows * 0.08; y < ground + 2; y++) {
    for (let x = lampX - cols * 0.12; x < lampX + cols * 0.12; x++) {
      const xi = Math.floor(x)
      const yi = Math.floor(y)
      const d = Math.hypot((xi - lampX) / cols, (yi - lampY) / rows) * 7
      if (d < 1 && cells[yi * cols + xi] < hill + 3) cells[yi * cols + xi] = glow + level((1 - d) * 0.9, 5, xi, yi)
    }
  }
  art.rect(lampX, lampY, 1, ground - lampY + 2, post)
  art.rect(lampX - 1, lampY - 2, 3, 2, lampHead)
  // Puddles, ringing.
  for (let i = 0; i < 4; i++) {
    const px = cols * (0.1 + 0.8 * random())
    const py = ground + (rows - ground) * (0.3 + 0.6 * random())
    const rx = cols * (0.06 + 0.05 * random())
    art.ellipse(px, py, rx, rx * 0.25, (x, y) => puddle + (Math.floor(Math.hypot(x - px, (y - py) * 4) * 0.7) % 8))
  }

  // The rain: tracks slanting down to the right, a drop every 9 cells.
  const rain = art.over(14, 30, false, (under, i) =>
    i === 0 ? mix(under, 0xc4d0e6, 0.6) : i < 3 ? mix(under, 0xa8b6d0, 0.35) : under)
  for (let x0 = -Math.floor(rows / 4); x0 < cols; x0 += 4 + Math.floor(random() * 4)) {
    const offset = Math.floor(random() * 14)
    for (let y = 0; y < rows; y++) {
      const x = x0 + Math.floor(y / 4)
      if (x >= 0 && x < cols) rain(y * cols + x, offset - y)
    }
  }
  return art
}

