// Snow: a cabin in the hills under the moon. Flakes drift down their own
// wavering tracks, smoke rises from the chimney, the windows glow and the
// stars twinkle.
import { Art, level, mix, noise } from './art'
import { random } from './random'

export function makeSnow(cols: number, rows: number) {
  const art = new Art(cols, rows)
  const cells = art.cells
  const sky = art.ramp(7, [[0, 0x060b1e], [0.6, 0x15264a], [1, 0x2c4a6e]])
  const moon = art.ramp(3, [[0, 0xc9d6e8], [1, 0xf6f8ff]])
  const halo = art.ramp(2, [[0, 0x203658], [1, 0x2c4670]])
  const snow = art.ramp(5, [[0, 0x4a6488], [0.5, 0x8aa4c6], [1, 0xe4eefa]])
  const pine = art.ramp(2, [[0, 0x08130f], [1, 0x14251c]])
  const log = art.ramp(3, [[0, 0x2a1810], [1, 0x5a3420]])
  const window = art.cycle([0xffc860, 0xffd27a, 0xf6b850, 0xffd27a, 0xffc860, 0xffe29a], 2, true)
  const stone = art.add(0x3a3a44)

  const n = noise(cols / 5)
  const tex = noise(3)
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) cells[y * cols + x] = sky + level(y / (rows * 0.7), 7, x, y)
  }
  const mx = cols * 0.78
  const my = rows * 0.18
  const mr = Math.min(cols, rows) * 0.06
  art.ellipse(mx, my, mr * 2.2, mr * 2.2, (x, y) => halo + level(1 - Math.hypot(x - mx, y - my) / (mr * 2.2), 2, x, y))
  art.ellipse(mx, my, mr, mr, (x, y) => moon + level(0.4 + 0.6 * tex(x * 2, y * 2), 3, x, y))

  // Two ridges of snow, the far one bluer.
  const near = new Int32Array(cols)
  for (let x = 0; x < cols; x++) {
    const far = Math.floor(rows * (0.5 + 0.08 * n(x, 1)))
    near[x] = Math.floor(rows * (0.66 + 0.06 * n(x * 1.4, 5)))
    for (let y = far; y < near[x]; y++) cells[y * cols + x] = snow + level(0.3 - (y - far) / rows, 5, x, y)
    for (let y = near[x]; y < rows; y++) cells[y * cols + x] = snow + level(0.95 - (y - near[x]) / (rows * 0.5) + 0.12 * (tex(x * 0.5, y) - 0.5), 5, x, y)
  }
  // Pines with snow on their boughs.
  const tree = (x: number, base: number, h: number) => {
    for (let k = 0; k < h; k++) {
      const w = Math.floor(k * 0.4 * ((k % 4) / 4 + 0.6))
      for (let dx = -w; dx <= w; dx++) {
        const xx = x + dx
        const yy = base - h + k
        if (xx < 0 || xx >= cols || yy < 0) continue
        cells[yy * cols + xx] = k % 4 === 0 && Math.abs(dx) < w ? snow + 4 : pine + (dx < 0 ? 0 : 1)
      }
    }
  }
  for (let x = 1; x < cols; x += 3 + Math.floor(random() * 6)) {
    if (x > cols * 0.3 && x < cols * 0.62) continue
    tree(x, near[x] + 2, Math.floor(rows * (0.08 + 0.1 * random())))
  }

  // The cabin.
  const cx = Math.floor(cols * 0.46)
  const cw = Math.floor(cols * 0.2)
  const base = near[cx] + Math.floor(rows * 0.04)
  const ch = Math.floor(rows * 0.1)
  for (let y = base - ch; y < base; y++) art.rect(cx - (cw >> 1), y, cw, 1, log + ((y - base) % 2 === 0 ? 0 : 2))
  const peak = Math.floor(cw * 0.6)
  for (let r = 0; r < peak; r++) {
    const w = Math.max(1, Math.round(((cw + 4) * (r + 1)) / peak))
    art.rect(cx - (w >> 1), base - ch - peak + r, w, 1, r > peak - 3 ? snow + 2 : snow + 4 - (r % 3 === 0 ? 1 : 0))
  }
  const chimX = cx + Math.floor(cw * 0.22)
  const chimTop = base - ch - Math.floor(peak * 0.7)
  art.rect(chimX, chimTop, 3, Math.floor(peak * 0.6), stone)
  art.rect(cx - Math.floor(cw * 0.3), base - Math.floor(ch * 0.7), 4, 3, window)
  art.rect(cx + Math.floor(cw * 0.12), base - Math.floor(ch * 0.7), 4, 3, window + 2)
  art.rect(cx - 1, base - Math.floor(ch * 0.55), 3, Math.floor(ch * 0.55), log)

  // Smoke rising, curling to the right as it goes.
  const smoke = art.over(12, 6, true, (under, i) => mix(under, 0xaab4c6, Math.max(0, 0.6 - Math.abs(i - 3) * 0.13)))
  for (let up = 1; up < rows * 0.35; up++) {
    const y = chimTop - up
    if (y < 0) break
    const sway = Math.sin(up * 0.18) * (1 + up * 0.06) + up * 0.25
    const w = 1 + Math.floor(up * 0.08)
    for (let dx = -w; dx <= w; dx++) {
      const x = Math.floor(chimX + 1 + sway + dx)
      if (x >= 0 && x < cols && random() < 1 - up / (rows * 0.4)) smoke(y * cols + x, -up + Math.floor(random() * 2))
    }
  }
  // Snowfall, the tracks wavering.
  const flake = art.over(14, 7, false, (under, i) => (i === 0 ? mix(under, 0xffffff, 0.85) : under))
  for (let x0 = 0; x0 < cols; x0 += 3 + Math.floor(random() * 3)) {
    const offset = Math.floor(random() * 14)
    const phase = random() * 6
    for (let y = 0; y < rows; y++) {
      const x = Math.floor(x0 + 1.5 * Math.sin(y * 0.12 + phase))
      if (x >= 0 && x < cols) flake(y * cols + x, offset - y)
    }
  }
  const twinkle = art.over(8, 2, true, (under, i) => (i === 3 ? mix(under, 0xffffff, 0.8) : i === 2 || i === 4 ? mix(under, 0xffffff, 0.3) : under))
  for (let i = Math.floor((cols * rows) / 500); i > 0; i--) {
    const x = Math.floor(random() * cols)
    const y = Math.floor(random() * rows * 0.4)
    if (cells[y * cols + x] < sky + 7) twinkle(y * cols + x, Math.floor(random() * 8))
  }
  return art
}

