// Aurora: the northern lights over a still lake. The curtains are ranges of
// green to violet laid across the sky, brighter toward their foot, and their
// waves run along them; the lake holds them again between its ripples.
import { Art, level, mix, noise } from './art'
import { random } from './random'

export function makeAurora(cols: number, rows: number) {
  const art = new Art(cols, rows)
  const cells = art.cells
  const sky = art.ramp(6, [[0, 0x03050d], [1, 0x0f1d33]])
  const ridge = art.ramp(2, [[0, 0x05080e], [1, 0x0d1520]])
  const pine = art.add(0x020405)
  const water = art.ramp(3, [[0, 0x050a14], [1, 0x0e1a2c]])
  // Four curtains by height, each a wave of brightness to run along it.
  const curtains: number[] = []
  const tones = [0x5effa6, 0x3fd6b0, 0x3d8fc8, 0x8a5ad6]
  for (let k = 0; k < 4; k++) {
    const colors: number[] = []
    for (let i = 0; i < 16; i++) {
      const wave = 0.5 + 0.5 * Math.cos((i / 16) * Math.PI * 2)
      colors.push(mix(0x0a1424, tones[k], (0.25 + 0.75 * wave) * (1 - k * 0.18)))
    }
    curtains.push(art.cycle(colors, 4 + k))
  }

  const horizon = Math.floor(rows * 0.6)
  const n = noise(cols / 3)
  const tex = noise(5)
  for (let y = 0; y < horizon; y++) {
    for (let x = 0; x < cols; x++) cells[y * cols + x] = sky + level(y / horizon, 6, x, y)
  }
  // The curtains: a foot that wanders, a height that varies, rays upward.
  for (let x = 0; x < cols; x++) {
    const foot = horizon * (0.62 + 0.18 * n(x, 0))
    const height = horizon * (0.25 + 0.3 * n(x * 0.7, 9))
    const ray = tex(x * 3, 0)
    for (let y = Math.max(0, Math.floor(foot - height)); y < foot; y++) {
      const up = (foot - y) / height // 0 at the foot, 1 at the top
      if (random() > 1.1 - up * up + ray * 0.2) continue
      const band = Math.min(3, Math.floor(up * 4 + 0.6 * (random() - 0.5)))
      cells[y * cols + x] = curtains[band] + ((Math.floor(x * 0.6 + 8 * n(x * 0.5, y * 0.05)) % 16) + 16) % 16
    }
  }
  // Stars where the lights are not.
  const twinkle = art.over(9, 2.2, true, (under, i) => (i === 4 ? mix(under, 0xffffff, 0.85) : i === 3 || i === 5 ? mix(under, 0xffffff, 0.35) : under))
  for (let i = Math.floor((cols * rows) / 250); i > 0; i--) {
    const x = Math.floor(random() * cols)
    const y = Math.floor(random() * horizon * 0.9)
    if (cells[y * cols + x] < sky + 6) twinkle(y * cols + x, Math.floor(random() * 9))
  }
  // Hills and pines along the far shore.
  const shore = new Int32Array(cols)
  for (let x = 0; x < cols; x++) {
    const top = Math.floor(horizon - rows * (0.04 + 0.06 * n(x * 1.5, 4)))
    shore[x] = top
    for (let y = top; y < horizon; y++) cells[y * cols + x] = ridge + level((y - top) / (horizon - top), 2, x, y)
  }
  for (let x = 0; x < cols; x += 1 + Math.floor(random() * 3)) {
    const h = Math.floor(rows * (0.02 + 0.04 * random()))
    for (let k = 0; k < h; k++) {
      const w = Math.floor(k * 0.3)
      art.rect(x - w, shore[x] - h + k, 2 * w + 1, 1, pine)
    }
  }
  // The lake: the sky again, upside down, under dark ripples.
  for (let y = horizon; y < rows; y++) {
    const from = 2 * horizon - y - 1
    const lines = (y - horizon) < rows * 0.15 ? 2 : 3
    for (let x = 0; x < cols; x++) {
      const wobble = Math.floor(2 * (tex(x * 0.5, y * 3) - 0.5) * (1 + (y - horizon) / (rows * 0.1)))
      const sx = Math.min(cols - 1, Math.max(0, x + wobble))
      const mirrored = from >= 0 ? cells[from * cols + sx] : sky
      const dark = (y - horizon) % lines === 0 || from < 0 || mirrored < curtains[0] && mirrored >= sky + 6
      cells[y * cols + x] = dark ? water + level(0.3 + (y - horizon) / rows, 3, x, y) : mirrored
    }
  }
  return art
}

