// Campfire: a clearing in the woods at night. The flames are ranges of color
// laid from the embers up, so they lick upward; sparks climb above them,
// fireflies blink at the edge of the trees.
import { Art, level, mix, noise } from './art'
import { random } from './random'

export function makeCampfire(cols: number, rows: number) {
  const art = new Art(cols, rows)
  const cells = art.cells
  const sky = art.ramp(5, [[0, 0x050711], [1, 0x141a2e]])
  const trees = art.ramp(3, [[0, 0x040806], [1, 0x0e1712]])
  const ground = art.ramp(8, [[0, 0x0c0d10], [0.5, 0x3a2418], [1, 0xa45a26]])
  const tent = art.ramp(4, [[0, 0x1a1418], [0.6, 0x6a3a22], [1, 0xc0702e]])
  const wood = art.ramp(3, [[0, 0x1e120c], [1, 0x5a3218]])
  const stone = art.ramp(3, [[0, 0x1c1a1e], [1, 0x6a5a52]])
  const core = art.cycle([0xfff6c8, 0xffe08a, 0xffc24a, 0xffa030, 0xffc24a, 0xffe08a, 0xffeeb0, 0xffd06a,
    0xffb03c, 0xff9428, 0xffb03c, 0xffd06a], 14, false)

  const groundY = Math.floor(rows * 0.62)
  const fx = cols * 0.5
  const fy = rows * 0.8
  const n = noise(cols / 6)
  const tex = noise(3)
  for (let y = 0; y < groundY; y++) {
    for (let x = 0; x < cols; x++) cells[y * cols + x] = sky + level(y / groundY, 5, x, y)
  }
  // The treeline: pines against the sky, lit a little from the fire.
  for (let x = 0; x < cols; x += 1 + Math.floor(random() * 3)) {
    const h = Math.floor(rows * (0.25 + 0.25 * n(x, 2) + 0.08 * random()))
    for (let k = 0; k < h; k++) {
      const w = Math.floor(k * 0.28 * (0.7 + 0.3 * ((k % 5) / 5)))
      art.rect(x - w, groundY - h + k + 2, 2 * w + 1, 1, trees + (k % 7 === 0 ? 1 : 0))
    }
  }
  // The ground, warmest round the fire.
  for (let y = groundY; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      const d = Math.hypot((x - fx) / cols, ((y - fy) / rows) * 1.8)
      cells[y * cols + x] = ground + level(Math.max(0, 1 - d * 2.4) + 0.25 * (tex(x * 2, y * 2) - 0.5), 8, x, y)
    }
  }
  // A tent, lit on the side facing the fire.
  const tx = cols * 0.2
  const tBase = Math.floor(rows * 0.74)
  const th = Math.floor(rows * 0.17)
  for (let k = 0; k < th; k++) {
    const w = Math.floor(k * 0.9)
    for (let dx = -w; dx <= w; dx++) {
      const x = Math.floor(tx + dx)
      const lit = dx > 0 ? 0.55 + 0.45 * (dx / (w + 1)) : 0.2 - 0.2 * (-dx / (w + 1))
      if (x >= 0 && x < cols) cells[(tBase - th + k) * cols + x] = Math.abs(dx) < k * 0.12 ? tent : tent + level(lit, 4, x, k)
    }
  }
  // Stones in a ring, logs crossed.
  for (let a = 0; a < 12; a++) {
    const sx = fx + Math.cos((a / 12) * Math.PI * 2) * cols * 0.09
    const sy = fy + 1 + Math.sin((a / 12) * Math.PI * 2) * rows * 0.025
    art.ellipse(sx, sy, cols * 0.017, rows * 0.012, (x, y) => stone + level(Math.sin((a / 12) * Math.PI * 2) * -0.4 + 0.6 - (y - sy) * 0.2, 3, x, y))
  }
  for (let k = -1; k <= 1; k += 2) {
    for (let i = -cols * 0.07; i < cols * 0.07; i++) {
      const x = Math.floor(fx + i)
      const y = Math.floor(fy - 1 + i * 0.25 * k)
      art.rect(x, y, 1, 2, wood + (i % 3 === 0 ? 2 : 1))
    }
  }
  // The flames: a teardrop, the index climbing from the embers, so the colors
  // lick upward; the outside of it comes and goes against the night.
  const flameH = rows * 0.2
  const flameW = cols * 0.075
  const outer = art.over(12, 14, false, (under, i) =>
    i < 3 ? 0xff8a24 : i < 5 ? 0xd2541a : i < 6 ? mix(under, 0x9a3010, 0.6) : under)
  for (let y = Math.floor(fy - flameH); y < fy; y++) {
    const up = (fy - y) / flameH // 0 at the embers, 1 at the tip
    const w = flameW * Math.pow(1 - up, 0.8) * Math.min(1, 0.55 + up * 4) * (0.8 + 0.4 * tex(3, y * 0.6))
    for (let x = Math.floor(fx - w - 2); x <= fx + w + 2; x++) {
      const side = Math.abs(x - fx) / Math.max(1, w)
      const lick = Math.floor((fy - y) + 5 * tex(x * 1.6, 0))
      if (side < 0.6 - up * 0.4) cells[y * cols + x] = core + ((lick % 12) + 12) % 12
      else if (side < 1.15) outer(y * cols + x, -lick)
    }
  }
  // Sparks climbing over the flames.
  const spark = art.over(16, 9, false, (under, i) => (i === 0 ? 0xffd27a : i === 1 ? mix(under, 0xff8a30, 0.6) : under))
  for (let s = 0; s < 7; s++) {
    let x = fx + (random() - 0.5) * flameW
    const offset = Math.floor(random() * 16)
    for (let y = Math.floor(fy - flameH); y > fy - flameH - rows * 0.25; y--) {
      x += (random() - 0.4) * 0.8
      const xi = Math.floor(x)
      if (y >= 0 && xi >= 0 && xi < cols) spark(y * cols + xi, offset + y)
    }
  }
  // Fireflies at the edge of the trees.
  const blink = art.over(12, 1.5, true, (under, i) => (i === 5 ? 0xd8ff7a : i === 4 || i === 6 ? mix(under, 0xb8e060, 0.45) : under))
  for (let i = 0; i < 14; i++) {
    const x = Math.floor(random() * cols)
    const y = Math.floor(groundY - rows * 0.15 + random() * rows * 0.2)
    if (Math.abs(x - fx) > cols * 0.15) blink(y * cols + x, Math.floor(random() * 12))
  }
  const twinkle = art.over(8, 2, true, (under, i) => (i === 3 ? mix(under, 0xffffff, 0.75) : under))
  for (let i = Math.floor((cols * rows) / 600); i > 0; i--) {
    const x = Math.floor(random() * cols)
    const y = Math.floor(random() * rows * 0.25)
    if (cells[y * cols + x] < sky + 5) twinkle(y * cols + x, Math.floor(random() * 8))
  }
  return art
}
